; F1 (banks 0-6 as memory; bank 7's registers by their slots; the segment slots written as memory). Generated by validation/v35s/onchip.py emit: the
; image also preloads the vector stubs and the data in onchip.py.
    BR main
handler:                ; 0103h: AL = the vector (from the stub)
    MOV BL, AL
    XOR AW, AW
    MOV DS0, AW
    MOV [7E00h], BL
    MOV BP, SP
    MOV AW, [BP]
    MOV [7E02h], AW
    MOV AW, [BP+2]
    MOV [7E04h], AW
    MOV AW, [BP+4]
    MOV [7E06h], AW
    MOV [7E08h], SP
    MOV AH, 02h         ; BRKI = 1: the OUT below does not trap
    MOV PSW, AH
    MOV DW, 0FF02h
    OUT DW, AL
    HALT
hspin:
    BR hspin
main:
    XOR AW, AW
    MOV SS, AW
    MOV SP, 7FFEh
    DI

    MOV AW, 0F000h
    MOV DS1, AW
    MOV AW, 0800h
    MOV DS0, AW
    DB 26h
    MOV word [0FEE0h], 0E1E0h
    DB 26h
    MOV word [0FEE2h], 0E3E2h
    DB 26h
    MOV word [0FEE4h], 0E5E4h
    DB 26h
    MOV word [0FEE6h], 0E7E6h
    MOV BW, 0FE00h
    MOV AL, 31h
    MOV CW, 00E0h
b_wr:
    DB 26h
    MOV [BW], AL
    ADD AL, 07h
    INC BW
    DBNZ b_wr
    MOV BW, 0FE00h
    MOV IY, 0000h
    MOV CW, 00E0h
b_rd:
    DB 26h
    MOV AL, [BW]
    MOV [IY], AL
    INC BW
    INC IY
    DBNZ b_rd
    MOV BW, 0FE00h
    MOV DW, 0A55Ah
    MOV CW, 0070h
w_wr:
    DB 26h
    MOV [BW], DW
    ADD DW, 0103h
    INC BW
    INC BW
    DBNZ w_wr
    MOV BW, 0FE01h
    MOV IY, 0100h
    MOV CW, 006Fh
w_rdo:
    DB 26h
    MOV AW, [BW]
    MOV [IY], AW
    INC BW
    INC BW
    INC IY
    INC IY
    DBNZ w_rdo
    MOV BW, 0FE00h
    MOV IY, 0200h
    MOV CW, 00E0h
w_rdb:
    DB 26h
    MOV AL, [BW]
    MOV [IY], AL
    INC BW
    INC IY
    DBNZ w_rdb
    MOV BW, 0FE01h
    MOV DW, 1357h
    MOV CW, 006Fh
o_wr:
    DB 26h
    MOV [BW], DW
    ADD DW, 0F1Fh
    INC BW
    INC BW
    DBNZ o_wr
    MOV BW, 0FE00h
    MOV IY, 0300h
    MOV CW, 00E0h
o_rd:
    DB 26h
    MOV AL, [BW]
    MOV [IY], AL
    INC BW
    INC IY
    DBNZ o_rd
    MOV AW, 1111h
    MOV CW, 2222h
    MOV DW, 3333h
    MOV BW, 4444h
    MOV BP, 6666h
    MOV IX, 7777h
    MOV IY, 8888h
    DB 26h
    MOV AW, [0FEFEh]
    MOV [0400h], AW
    DB 26h
    MOV AW, [0FEFCh]
    MOV [0402h], AW
    DB 26h
    MOV AW, [0FEFAh]
    MOV [0404h], AW
    DB 26h
    MOV AW, [0FEF8h]
    MOV [0406h], AW
    DB 26h
    MOV AW, [0FEF6h]
    MOV [0408h], AW
    DB 26h
    MOV AW, [0FEF4h]
    MOV [040Ah], AW
    DB 26h
    MOV AW, [0FEF2h]
    MOV [040Ch], AW
    DB 26h
    MOV AW, [0FEF0h]
    MOV [040Eh], AW
    DB 26h
    MOV AW, [0FEEEh]
    MOV [0410h], AW
    DB 26h
    MOV AW, [0FEECh]
    MOV [0412h], AW
    DB 26h
    MOV AW, [0FEEAh]
    MOV [0414h], AW
    DB 26h
    MOV AW, [0FEE8h]
    MOV [0416h], AW
    DB 26h
    MOV AL, [0FEFFh]
    MOV [0418h], AL
    DB 26h
    MOV AL, [0FEFDh]
    MOV [0419h], AL
    DB 26h
    MOV AW, [0FEFDh]
    MOV [041Ah], AW
    ; the slots written, the registers read
    DB 26h
    MOV word [0FEFCh], 0A1A2h
    MOV [0440h], CW
    DB 26h
    MOV word [0FEFAh], 0B1B2h
    MOV [0442h], DW
    DB 26h
    MOV word [0FEF8h], 0C1C2h
    MOV [0444h], BW
    DB 26h
    MOV word [0FEF4h], 0D1D2h
    MOV [0446h], BP
    DB 26h
    MOV word [0FEF2h], 0E1E2h
    MOV [0448h], IX
    DB 26h
    MOV word [0FEF0h], 0F1F2h
    MOV [044Ah], IY
    DB 26h
    MOV word [0FEFEh], 9192h
    MOV [044Ch], AW
    DB 26h
    MOV byte [0FEFCh], 5Ah
    MOV [044Eh], CW
    DB 26h
    MOV byte [0FEFBh], 6Bh
    MOV [0450h], DW
    MOV AW, SP
    DB 26h
    MOV word [0FEF6h], 0FF0h
    MOV [0452h], SP
    MOV SP, AW
    ; an odd word across two registers' slots: AH and CL
    DB 26h
    MOV word [0FEFDh], 7C7Dh
    MOV [0454h], AW
    MOV [0456h], CW
    DB 26h
    MOV word [0FEE8h], 0900h
    MOV AW, DS0
    MOV CL, [0F00h]
    MOV BW, 0800h
    MOV DS0, BW
    MOV [0460h], AW
    MOV [0462h], CL
    ; SS (EEA) <- 0010h: MOV AW,SS and a read of SS:[6F00h] (06F00h holds 33h, 07000h 44h)
    DB 26h
    MOV word [0FEEAh], 0010h
    MOV AW, SS
    DB 36h
    MOV CL, [6F00h]
    XOR BW, BW
    MOV SS, BW
    MOV [0464h], AW
    MOV [0466h], CL
    ; DS1 (EEE) <- 1000h: MOV AW,DS1 and a read of DS1:[0F00h] (10F00h holds 55h)
    DB 26h
    MOV word [0FEEEh], 1000h
    MOV AW, DS1
    DB 26h
    MOV CL, [0F00h]
    MOV BW, 0F000h
    MOV DS1, BW
    MOV [0468h], AW
    MOV [046Ah], CL
    ; PS (EEC) <- 0010h: execution lands at +100h if PS moves (two copies of the sled)
    DB 0EAh, 00h, 20h, 00h, 00h  ; BR far 0000:2000h
ps_back:
    MOV AW, PS
    MOV [0474h], AW
    ; PS <- 0010h, then a near branch (BR $+2): the refill's PS
    DB 0EAh, 00h, 22h, 00h, 00h  ; BR far 0000:2200h
ps_back2:
    MOV AW, PS
    MOV [047Ah], AW
    MOV BW, 0FE00h
    MOV IY, 0500h
    MOV CW, 0100h
dump:
    DB 26h
    MOV AL, [BW]
    MOV [IY], AL
    INC BW
    INC IY
    DBNZ dump
    MOV DW, 0FF00h
    OUT DW, AL
    HALT
done:
    BR done

